async function startCamera(){if(stream){stopCamera();return}if(!navigator.mediaDevices?.getUserMedia){msg('warn','Camera access is unavailable here. Use the QR/manual entry field or open the page on localhost/HTTPS.');return}try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});const v=$('video');v.srcObject=stream;v.classList.remove('hide');await v.play();$('scanFrame').classList.add('live');$('cameraBtn').textContent='Stop QR scanner';$('scanHint').textContent='Hold the QR code inside the frame';if(!('BarcodeDetector'in window)){msg('warn','This browser does not expose QR BarcodeDetector. Camera preview is on; use manual entry instead.');return}const detector=new BarcodeDetector({formats:['qr_code']});msg('','Scanning for QR codes…');scannerTimer=setInterval(async()=>{try{if(!stream||currentScan)return;const hits=await detector.detect(v);if(hits.length&&hits[0].rawValue)lookupCode(hits[0].rawValue)}catch(e){}},350)}catch(err){stopCamera();msg('bad',err.name==='NotAllowedError'?'Camera permission denied. Allow camera access or use manual entry.':'Could not start the camera. Use manual entry.')}}
function stopCamera(){if(scannerTimer){clearInterval(scannerTimer);scannerTimer=null}if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}const v=$('video');if(v){v.srcObject=null;v.classList.add('hide')}$('scanFrame').classList.remove('live');$('cameraBtn').textContent='Start QR scanner';$('scanHint').textContent='Point the camera at the shipment QR code'}$('cameraBtn').addEventListener('click',startCamera);
