function costOfRecipe(r){return r.ingredients.reduce((s,x)=>s+(item(x.id)?.cost||0)*Number(x.q),0)}function foodPct(r){return r.price?costOfRecipe(r)/r.price*100:0}function suggestedPrice(r){return costOfRecipe(r)/(Math.max(1,Math.min(100,Number(targetPct)||30))/100)}
