function renderPendingCounts(){const manager=['manager','admin'].includes(STAFF_ROLE.toLowerCase()),pending=pendingCounts||[];const prefix='Enter physical counts. Negative count differences require a reason; only a manager can apply adjustments.';$('varianceNote').innerHTML=escapeHtml(prefix)+(pending.length?'<div class="pending-count-list"><b>Awaiting manager approval</b>'+pending.map(c=>`<div class="line-row"><span>${escapeHtml(c.id)} · ${escapeHtml(c.storageZone)} · ${Number(c.itemCount)||0} item(s)</span><span>${escapeHtml(c.countedBy)} · ${escapeHtml(displayTime(c.submittedAt))}</span>${manager?`<button type="button" class="btn small red" data-count-approve="${escapeAttr(c.id)}">Approve count</button>`:'<span>Pending</span>'}</div>`).join('')+'</div>':'')}
function updateVariancePreview(){document.querySelectorAll('#varianceBody tr').forEach(tr=>{const i=item(tr.dataset.varId),input=tr.querySelector('.physical-input'),cell=tr.querySelector('.variance-value');if(input.value===''){cell.textContent='—';return}try{const actual=convertQtyToBase(Number(input.value),tr.querySelector('.physical-unit').value,i,tr.querySelector('.physical-factor').value),v=r2(actual-expectedStock(i));cell.textContent=(v>0?'+':'')+qtyFmt(v)+' '+i.unit;cell.classList.toggle('over-target',v<0);cell.classList.toggle('on-target',v>0)}catch(err){cell.textContent='⚠ '+err.message;cell.classList.add('over-target');cell.classList.remove('on-target')}})}
 $('saveCounts').addEventListener('click',async()=>{const entries=[];for(const tr of [...$('varianceBody').querySelectorAll('tr')]){const i=item(tr.dataset.varId),input=tr.querySelector('.physical-input'),reason=tr.querySelector('.variance-reason').value;if(input.value===''||!Number.isFinite(Number(input.value))||Number(input.value)<0)continue;const quantity=Number(input.value),unit=tr.querySelector('.physical-unit').value,factor=Number(tr.querySelector('.physical-factor').value||0),wasteStage=tr.querySelector('.count-waste-stage').value;let actual;try{actual=convertQtyToBase(quantity,unit,i,factor)}catch(error){toast(i.name+': '+error.message);return}const variance=rq(actual-i.stock);if(Math.abs(variance)>=.001&&!reason){toast('Select a variance reason for '+i.name+'.');tr.querySelector('.variance-reason').focus();return}if(variance<-.001&&reason.startsWith('Waste: ')&&!wasteStage){toast('Select the waste stage for '+i.name+'.');return}entries.push({ingredient_id:i.id,quantity,unit,conversion_factor:factor||null,reason:reason||null,waste_stage:reason.startsWith('Waste: ')?wasteStage:null})}if(!entries.length)return toast('Enter at least one physical count.');const button=$('saveCounts'),countPayload={storage_zone:$('poCommissary').value||'Restaurant',items:entries};button.disabled=true;try{const data=await inventoryPost(inventoryRoutes.counts,countPayload);if(data.count.status==='pending_approval')pendingCounts.unshift(data.count);if(data.stocks)Object.entries(data.stocks).forEach(([id,stock])=>{const i=item(id);if(i)i.stock=Number(stock)});renderAll();toast(data.message);if(data.count.status==='approved')window.location.reload()}catch(error){if(error.networkFailure||!navigator.onLine){queueOfflineAction('physical-count.submit',countPayload);toast('Physical count saved on this device; stock will update after sync.')}else toast(error.message)}finally{button.disabled=false}});
