function exportXlsx(){const rows=exportRows(),headers=Object.keys(rows[0]||{timestamp:'',staffId:'',action:'',sku:'',item:'',change:'',unit:'',commissary:'',bin:'',reference:'',note:'',cost:''}),table=[headers,...rows.map(o=>headers.map(h=>o[h]))];const cols='ABCDEFGHIJKLMNOPQRSTUVWXYZ';const sheetRows=table.map((row,ri)=>`<row r="${ri+1}">${row.map((v,ci)=>{const ref=(ci<26?cols[ci]:'A'+cols[ci-26])+(ri+1);if(typeof v==='number'&&Number.isFinite(v))return `<c r="${ref}" t="n"><v>${v}</v></c>`;return `<c r="${ref}" t="inlineStr"><is><t xml:space="preserve">${xmlEscape(v)}</t></is></c>`}).join('')}</row>`).join('');const summary=rangeStats(auditRowsInRange());const files=[['[Content_Types].xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/worksheets/sheet2.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>'],['_rels/.rels','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'],['xl/workbook.xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Raw Data" sheetId="1" r:id="rId1"/><sheet name="Summary" sheetId="2" r:id="rId2"/></sheets></workbook>'],['xl/_rels/workbook.xml.rels','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet2.xml"/></Relationships>'],['xl/worksheets/sheet1.xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>'+sheetRows+'</sheetData></worksheet>'],['xl/worksheets/sheet2.xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData><row r="1"><c r="A1" t="inlineStr"><is><t>Metric</t></is></c><c r="B1" t="inlineStr"><is><t>Value</t></is></c></row>'+[['Period',formatRange(auditStart,auditEnd)],['Audit events',summary.entries],['QR receipts',summary.receipts],['Recipe deductions',summary.usage],['Waste cost (PHP)',r2(summary.wasteCost)]].map((r,i)=>`<row r="${i+2}"><c r="A${i+2}" t="inlineStr"><is><t>${xmlEscape(r[0])}</t></is></c><c r="B${i+2}" ${typeof r[1]==='number'?'t="n"':'t="inlineStr"'}>${typeof r[1]==='number'?`<v>${r[1]}</v>`:`<is><t>${xmlEscape(r[1])}</t></is>`}</c></row>`).join('')+'</sheetData></worksheet>']];downloadBlob(zipStore(files),'passenger-seat-audit-'+auditStart+'_'+auditEnd+'.xlsx');toast('Raw XLSX exported')}
function exportExecutivePdf(){const rows=currentHistoryRows(),summary=rangeStats(auditRowsInRange()),w=window.open('','_blank');if(!w){toast('Allow pop-ups to prepare the PDF summary');return}const table=rows.slice(0,1000).map(x=>`<tr><td>${escapeHtml(displayTime(x.timestamp))}</td><td>${escapeHtml(x.staff)}</td><td>${escapeHtml(x.action)}</td><td>${escapeHtml(x.itemName||x.ref||'—')}</td><td>${x.change>0?'+':''}${qtyFmt(x.change)} ${escapeHtml(item(x.itemId)?.unit||'')}</td><td>${escapeHtml(x.commissary)}</td></tr>`).join('');w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Passenger Seat Executive Audit Summary</title><style>body{font:12px Arial,sans-serif;color:#202124;padding:26px}h1{color:#c62828}small{color:#666}.metrics{display:flex;gap:12px;margin:18px 0}.m{border:1px solid #ddd;border-radius:9px;padding:12px;flex:1}.m b{display:block;font-size:20px;margin-top:5px}table{width:100%;border-collapse:collapse;font-size:10px}th,td{padding:7px;border-bottom:1px solid #ddd;text-align:left}th{background:#f6e7e7}@media print{button{display:none}body{padding:0}}</style></head><body><h1>Passenger Seat · Executive Summary</h1><p><b>History & Audit</b> · ${escapeHtml(formatRange(auditStart,auditEnd))}</p><p><small>Prepared ${escapeHtml(displayTime(isoNow()))} · ${escapeHtml(STAFF_NAME)} (#${escapeHtml(STAFF_ID)}) · Selected period local report</small></p><div class="metrics"><div class="m">Audit events<b>${summary.entries}</b></div><div class="m">QR receipts<b>${summary.receipts}</b></div><div class="m">Recipe deductions<b>${summary.usage}</b></div><div class="m">Waste cost<b>${escapeHtml(money(summary.wasteCost))}</b></div></div><h2>Inventory audit details</h2><table><thead><tr><th>Timestamp</th><th>Staff</th><th>Action</th><th>Ingredient / Ref</th><th>Change</th><th>Commissary</th></tr></thead><tbody>${table||'<tr><td colspan="6">No events for this period.</td></tr>'}</tbody></table><p><small>Generated from saved inventory movement and audit records.</small></p><script>window.onload=()=>setTimeout(()=>window.print(),300)<\/script></body></html>`);w.document.close()}
$('exportMenu').addEventListener('click',e=>{const b=e.target.closest('[data-export]');if(!b)return;$('exportMenu').hidden=true;$('exportToggle').setAttribute('aria-expanded','false');if(b.dataset.export==='csv')exportCsv();else if(b.dataset.export==='xlsx')exportXlsx();else exportExecutivePdf()});

