const inventoryLogoutModal=$('inventoryLogoutModal'),inventoryLogoutButton=$('logoutBtn');
inventoryLogoutButton?.addEventListener('click',()=>{inventoryLogoutModal.hidden=false;inventoryLogoutModal.querySelector('[data-logout-cancel]').focus()});
inventoryLogoutModal?.querySelectorAll('[data-logout-cancel]').forEach(button=>button.addEventListener('click',()=>{inventoryLogoutModal.hidden=true;inventoryLogoutButton.focus()}));
inventoryLogoutModal?.addEventListener('click',event=>{if(event.target===inventoryLogoutModal){inventoryLogoutModal.hidden=true;inventoryLogoutButton.focus()}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&inventoryLogoutModal&&!inventoryLogoutModal.hidden){inventoryLogoutModal.hidden=true;inventoryLogoutButton.focus()}});

function inventoryAlertRows(){const rows=[];items.forEach(i=>{if(i.stock<=0)rows.push({key:`stock:${i.id}:out`,title:'Out of stock',body:`${i.name} has no available stock.`,itemId:i.id});else if(i.stock<=i.min)rows.push({key:`stock:${i.id}:low`,title:'Low stock',body:`${i.name}: ${qtyFmt(i.stock)} ${i.unit} remaining (minimum ${qtyFmt(i.min)}).`,itemId:i.id});if(i.exp&&daysTo(i.exp)<=7)rows.push({key:`expiry:${i.id}:${i.exp}`,title:daysTo(i.exp)<0?'Expired ingredient':'Near expiry',body:`${i.name} best before ${i.exp}${daysTo(i.exp)<0?' (expired)':` (${daysTo(i.exp)} day(s))`}.`,itemId:i.id})});return rows}
function notificationReadKeys(){try{const parsed=JSON.parse(localStorage.getItem(NOTIFICATIONS_READ_KEY)||'[]');return Array.isArray(parsed)?parsed.filter(x=>typeof x==='string'):[]}catch(error){return []}}
function saveNotificationReadKeys(keys){try{localStorage.setItem(NOTIFICATIONS_READ_KEY,JSON.stringify([...new Set(keys)]))}catch(error){toast('Could not save notification read status on this device.')}}
function renderInventoryNotifications(){const rows=inventoryAlertRows(),activeKeys=new Set(rows.map(row=>row.key)),read=notificationReadKeys().filter(key=>activeKeys.has(key));if(read.length!==notificationReadKeys().length)saveNotificationReadKeys(read);const readSet=new Set(read),unread=rows.filter(row=>!readSet.has(row.key));$('inventoryUnreadCount').textContent=String(unread.length);$('inventoryUnreadCount').hidden=unread.length===0;$('inventoryMarkAllRead').disabled=unread.length===0;$('inventoryNotificationList').innerHTML=rows.length?rows.map(row=>`<button type="button" class="inventory-notify-item ${readSet.has(row.key)?'':'unread'}" data-notification-key="${escapeAttr(row.key)}"><i aria-hidden="true"></i><span class="inventory-notify-copy"><strong>${escapeHtml(row.title)}</strong><span>${escapeHtml(row.body)}</span><small>Open inventory overview</small></span></button>`).join(''):'<p class="inventory-notify-empty">You\'re all caught up. No new notifications.</p>'}
function closeInventoryNotifications(){const panel=$('inventoryNotificationPanel');panel.hidden=true;$('inventoryBell').setAttribute('aria-expanded','false')}
$('inventoryBell').addEventListener('click',()=>{const panel=$('inventoryNotificationPanel'),opening=panel.hidden;panel.hidden=!opening;$('inventoryBell').setAttribute('aria-expanded',String(opening));if(opening)renderInventoryNotifications()});
$('inventoryMarkAllRead').addEventListener('click',()=>{saveNotificationReadKeys([...notificationReadKeys(),...inventoryAlertRows().map(row=>row.key)]);renderInventoryNotifications()});
$('inventoryNotificationList').addEventListener('click',event=>{const entry=event.target.closest('[data-notification-key]');if(!entry)return;saveNotificationReadKeys([...notificationReadKeys(),entry.dataset.notificationKey]);renderInventoryNotifications();closeInventoryNotifications();setView('inventory');setTimeout(()=>$('inventoryAlerts').scrollIntoView({behavior:'smooth',block:'center'}),80)});
$('viewInventoryNotifications').addEventListener('click',()=>{closeInventoryNotifications();setView('inventory');setTimeout(()=>$('inventoryAlerts').scrollIntoView({behavior:'smooth',block:'center'}),80)});
document.addEventListener('click',event=>{if(!$('inventoryNotificationPanel').hidden&&!$('inventoryBell').parentElement.contains(event.target))closeInventoryNotifications()});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('inventoryNotificationPanel').hidden){closeInventoryNotifications();$('inventoryBell').focus()}});
function renderRecentReceipts(){const rec=audit.filter(a=>a.action==='QR received').slice(0,8);$('recentReceipts').innerHTML=rec.length?rec.map(a=>`<tr><td>${displayTime(a.timestamp)}</td><td>${escapeHtml(a.itemName)}</td><td>+${qtyFmt(a.change)} ${escapeHtml(item(a.itemId)?.unit||'')}</td><td>${escapeHtml(a.commissary)}</td><td>${escapeHtml(a.ref)}<div class="tiny">${escapeHtml(a.note.match(/batch [^;]+/i)?.[0]||'')}</div></td></tr>`).join(''):'<tr><td colspan="5" class="empty">No receipts recorded yet.</td></tr>'}
function updateConnectionBadge(){const count=syncQueue.length;$('syncStatus').textContent=!navigator.onLine?`Offline · ${count} action(s) queued`:count?`${count} action(s) awaiting sync`:'Live database snapshot';$('syncQueueSummary').textContent=count?`${count} action(s) saved on this device for ${STAFF_NAME} (#${STAFF_ID})`:'No pending actions';$('syncNow').disabled=!count||!navigator.onLine}
async function flushSyncQueue(){if(!navigator.onLine||syncInProgress||!syncQueue.length){updateConnectionBadge();return}syncInProgress=true;updateConnectionBadge();let shouldReload=false;try{const batch=syncQueue.slice(0,50);const response=await fetch(inventoryRoutes.sync,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json','X-Requested-With':'XMLHttpRequest','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.content||''},body:JSON.stringify({events:batch})});if(!response.ok)throw new Error(`Sync request failed (${response.status}).`);const data=await response.json();const completed=new Set();const errors=[];for(const result of data.results||[]){if(result.status_code>=500)continue;if(result.status_code>=400){errors.push(result.body?.message||`Queued action failed (${result.status_code}).`);continue}completed.add(result.idempotency_key);shouldReload=true}syncQueue=syncQueue.filter(event=>!completed.has(event.idempotency_key));persistOutbox();updateConnectionBadge();if(errors.length)toast(errors[0]);else if(shouldReload){toast('Queued inventory actions synced.');setTimeout(()=>location.reload(),500)}}catch(error){toast('Sync paused; queued actions are still saved on this device.')}finally{syncInProgress=false;updateConnectionBadge()}}
$('syncNow').addEventListener('click',()=>void flushSyncQueue());
window.addEventListener('online',()=>{updateConnectionBadge();void flushSyncQueue()});window.addEventListener('offline',updateConnectionBadge);
function renderAll(){renderPO();renderCosting();renderWaste();renderInventory();renderHistory();renderRecentReceipts();renderInventoryNotifications();updateQuantityUnits()}
