populateWasteChoices();populateForms();$('fieldPO').innerHTML='<option value="">No PO linked</option>';initHistoryRange();setTheme(state.theme||'light');renderAll();updateConnectionBadge();if(syncQueue.length&&navigator.onLine)setTimeout(()=>void flushSyncQueue(),300);const startTab=location.hash.slice(1);setView(['receive','po','costing','waste','inventory','history'].includes(startTab)?startTab:'receive');
